@php($items = [['Home', route('home'), 'home'], ['Services', route('services.index'), 'pets'], ['FAQ', route('faq'), 'help'], ['Contact', route('contact'), 'email']])
<nav x-data="{ hidden: false, last: 0 }" x-init="window.addEventListener('scroll', () => { const y = window.scrollY; hidden = y > 100 && y > last + 5; if (y < 100 || y < last - 5) hidden = false; last = y })" x-show="!hidden" x-transition:enter="transition-transform" x-transition:enter-start="translate-y-full" x-transition:leave="transition-transform" x-transition:leave-end="translate-y-full" class="fixed inset-x-0 bottom-0 z-40 grid grid-cols-4 border-t border-surface-purple bg-surface pb-[env(safe-area-inset-bottom)] md:hidden" aria-label="Mobile navigation">
    @foreach ($items as [$label, $href, $icon]) @php($path = trim(parse_url($href, PHP_URL_PATH) ?: '/', '/')) @php($active = $path === '' ? request()->path() === '/' : request()->is($path.'*'))<a href="{{ $href }}" class="relative flex min-h-16 flex-col items-center justify-center gap-1 text-[0.6875rem] font-medium {{ $active ? 'text-primary' : 'text-primary-dark/50' }}" @if($active) aria-current="page" @endif><x-waggies.icon name="{{ $icon }}" size="22" variant="{{ $active ? 'filled' : 'outlined' }}" /><span>{{ $label }}</span>@if($active)<span class="absolute left-1/2 top-0 h-0.5 w-8 -translate-x-1/2 rounded-full bg-primary" aria-hidden="true"></span>@endif</a>@endforeach
</nav>
